/// The service component is not an Android SDK class, so it remains a
/// hand-written class lookup. Android framework bindings are generated by
/// `tools/jnigen.dart`.
abstract final class AndroidApi {
  static final JClass vpnServiceComponentClass = JClass.forName(
    'io/aote/vpnService/ClashVpnService',
  );

  static bool isVpnActive(Context context) {
    return VpnStateStore.isVpnActive(context);
  }
}
